export type Connection = {
    weight: number
    deltaWeight: number
}

export class Layer extends Array<Neuron> {

}

export class Neuron {
    // [0.0...1.0] overall net training rate
    private static eta: number = 0.15

    // [0.0...n] multiplier of last weight change [momentum]
    private static alpha: number = 0.5

    private static transferFunction(x: number): number {
        // tanh - output range [-1.0..1.0]
        return Math.tanh(x)
    }

    private static transferFunctionDerivative(x: number): number {
        // tanh derivative
        return 1.0 - x * x;
    }

    // randomWeight: 0 - 1
    private static randomWeight(): number {
        return Math.random()
    }

    private sumDOW(nextLayer: Layer): number {
        let sum: number = 0.0

        // Sum our contributions of the errors at the nodes we feed

        for (let i in nextLayer) {
            sum += this.m_outputWeights[i].weight * nextLayer[i].m_gradient
        }

        return sum
    }

    private m_outputVal: number
    private m_outputWeights: Array<Connection>
    private m_myIndex: number
    private m_gradient: number

    constructor(numOutputs, myIndex) {
        this.m_outputWeights = []

        for (let i = 0; i < numOutputs; i++) {
            this.m_outputWeights.push({ weight: Neuron.randomWeight(), deltaWeight: 0.0 })
        }

        this.m_myIndex = myIndex
    }

    setOutputVal(val: number): void {
        this.m_outputVal = val
    }

    getOutputVal(): number {
        return this.m_outputVal
    }

    feedForward(prevLayer: Layer): void {
        let sum = 0.0

        // Sum the previous layer's outputs (which are our inputs)
        // Include the bias node from the previous layer.

        for (let i in prevLayer) {
            sum += prevLayer[i].getOutputVal() *
                   prevLayer[i].m_outputWeights[this.m_myIndex].weight
        }

        this.m_outputVal = Neuron.transferFunction(sum)
    }

    calcOutputGradients(targetVals: number): void {
        const delta = targetVals - this.m_outputVal

        this.m_gradient = delta * Neuron.transferFunctionDerivative(this.m_outputVal)
    }

    calcHiddenGradients(nextLayer: Layer): void {
        const dow = this.sumDOW(nextLayer)

        this.m_gradient = dow * Neuron.transferFunctionDerivative(this.m_outputVal)
    }

    updateInputWeights(prevLayer: Layer): void {
        // The weights to be updated are in the Connection container
        // in the nuerons in the preceding layer

        for (let i in prevLayer) {
            const neuron = prevLayer[i]
            const oldDeltaWeight = neuron.m_outputWeights[this.m_myIndex].deltaWeight

            const newDeltaWeight =
                // Individual input, magnified by the gradient and train rate:
                Neuron.eta * neuron.getOutputVal() * this.m_gradient
                // Also add momentum = a fraction of the previous delta weight
                + Neuron.alpha * oldDeltaWeight
            neuron.m_outputWeights[this.m_myIndex].deltaWeight = newDeltaWeight
            neuron.m_outputWeights[this.m_myIndex].weight += newDeltaWeight
        }
    }
}

export class Net {
    private m_layers: Array<Layer> // m_layers[layerNum][neuronNum]
    private m_error: number
    private m_recentAverageError: number
    private static m_recentAverageSmoothingFactor: number = 100.0

    constructor(topology: Array<number>) {
        this.m_layers = []

        const numLayers = topology.length

        for (let l=0; l<numLayers; l++) {
            const layer = new Layer()

            // numOutputs of layer[i] is the numInputs of layer[i+1]
            // numOutputs of last layer is 0
            const numOutputs = l == topology.length - 1 ? 0 : topology[l + 1]

            // We have made a new Layer, now fill it ith neurons, and
            // add a bias neuron to the layer:
            for (let neuronNum = 0; neuronNum <= topology[l]; ++neuronNum) {
                layer.push(new Neuron(numOutputs, neuronNum))
            }

            // Force the bias node's output value to 1.0. It's the last neuron created above
            layer[topology[l]].setOutputVal(1.0)

            this.m_layers.push(layer)
        }
    }

